INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd1-prekrasnoe-daleko', 'Прекрасное далёко',
  (SELECT id FROM "Authors" WHERE name = 'Александр Шилякин' ORDER BY id LIMIT 1),
  'mrd1/mrd1-prekrasnoe-daleko.jpg', 'data:image/jpeg;base64,', 948, 714,
  'Зелёный июнь стоял до окон третьего этажа. На вспоротом диване сидели девушки, смотрели, как зеленеет июнь за окном, дует им в лица, прохладный. Из подъезда через открытую дверь тянет в брошенную квартиру запахом сигар', '[{"kind":"image","path":"mrd1/mrd1-prekrasnoe-daleko.jpg","caption":null},{"kind":"paragraph","text":"Зелёный июнь стоял до окон третьего этажа. На вспоротом диване сидели девушки, смотрели, как зеленеет июнь за окном, дует им в лица, прохладный. Из подъезда через открытую дверь тянет в брошенную квартиру запахом сигарет, сыро и тихо в подъезде, курят на лестнице юноши постарше."},{"kind":"paragraph","text":"— А тебе нельзя! — смеётся юноша, поднимает сигарету повыше, чтобы мальчик не дотянулся."},{"kind":"paragraph","text":"Девушки смеются. Мальчик оглянулся на девочек и пнул красивого, высокого юношу."},{"kind":"paragraph","text":"— Ах ты зараза!"},{"kind":"paragraph","text":"Красивый юноша махнул ногой в сторону мальчика, рукой с сигаретой взмахнул, мальчик от ноги увернулся и схватил сигарету из руки юноши."},{"kind":"paragraph","text":"Девушки смеются. Мальчик сунул сигарету в зубы и пошёл по бетонному полу, хрустнуло под ногой битое стекло. Зелёный июнь покачивается за пустой оконной рамой, мальчик с сигаретой сидит на подоконнике."},{"kind":"paragraph","text":"— Сколько время? — спрашивает мальчик."},{"kind":"paragraph","text":"— Два часа, — отвечает ему юноша, который на газете колбасу режет коротким ножиком."},{"kind":"paragraph","text":"— Дай программу посмотреть, — говорит мальчик юноше."},{"kind":"paragraph","text":"Юноша взял несколько листов из газеты и подал мальчику. Мальчик посмотрел программку и сказал:"},{"kind":"paragraph","text":"— По первому каналу гостья из будущего идёт — включай, Сашка! — девушки смеются."},{"kind":"paragraph","text":"Саша встал с подоконника, бросил окурок в банку из-под кофе. Большой телевизор стоял на табуретке перед диваном. Саша присел перед ним и включил, экран горел сначала тускло, потом просветлел, помехи белые с серым пошли. Саша поправлял антенну одной рукой, другой переключал передачи."},{"kind":"paragraph","text":"Юноши вошли в квартиру из подъезда и сели на диван, девушек посадили себе на колени. Экран моргнул, чёрно-белые люди на экране стали ходить."},{"kind":"paragraph","text":"Из трёхлитровой банки по очереди отпивали пиво юноши и девушки, колбасу, порезанную кружочками, брали с газеты, смотрели телевизор."},{"kind":"paragraph","text":"— Газета прошлогодняя, дурак, — сказал один из юношей, заглянул в программку, потом посмотрел в телевизор."},{"kind":"paragraph","text":"— Сам дурак, смотри, гостья из будущего идёт, — сказал Саша."},{"kind":"paragraph","text":"— Интересно, как это, — юноша отложил жирную от колбасы газету, жирной от колбасы рукой девушку обнял."},{"kind":"paragraph","text":"— Да вот так, — сказал ему Саша."},{"kind":"paragraph","text":"— Пиво закончилось, — сказал другой юноша."},{"kind":"paragraph","text":"— Кто пойдет? — спросили девушки."},{"kind":"paragraph","text":"— Я схожу, — сказал Саша."},{"kind":"paragraph","text":"Юноши полезли в карманы, откидываясь на спинку дивана. Бросали монеты на стол, застеленный газетами. Саша собрал жирные от юношеских пальцев монеты и положил в карман, взял пустую стеклянную банку и пошёл к двери."},{"kind":"paragraph","text":"— Если есть кто сейчас у ларька, спроси купить, — кто-то сказал ему вслед."},{"kind":"paragraph","text":"— Или Леонида Семёновича попроси, он свой мужик, — сказал ему вслед ещё кто-то."},{"kind":"paragraph","text":"— Разберусь, — сказал Саша."},{"kind":"paragraph","text":"В прохладном подъезде шёл Саша вниз по лестнице, заглядывал в пустые квартиры. Лежали там на полу старые календари, страницы из книг, зеркала в трельяже разбитые, а в окнах разбитых зеленеет июнь. Больше не живут здесь, разбиты зеркала, в которые когда-то смотрели на себя женщины."},{"kind":"paragraph","text":"У подъезда пахнут деревья в цвету, спят под деревьями мужики. В глубине двора, за столом в тени цветущих деревьев сидит Леонид Семёнович с кем-то перед шахматной доской, берёт короля и бьет им по доске."},{"kind":"paragraph","text":"— Сливай воду, Стёпа! — громко сказал Леонид Семёнович."},{"kind":"paragraph","text":"Стёпа нахмурился и долго на доску смотрел. Потом плюнул в сторону и встал из-за стола. Закурил и отвернулся, посматривал на Леонида Семёновича из-за плеча."},{"kind":"paragraph","text":"— Ты на меня не зыркай! Тебя, дурака, только учить! — смеялся Леонид Семёнович."},{"kind":"paragraph","text":"Саша подошёл к столу и посмотрел на доску."},{"kind":"paragraph","text":"— Играть будешь, Сашок?"},{"kind":"paragraph","text":"— Нет, Леонид Семёнович, не буду. Мне бы пива купить."},{"kind":"paragraph","text":"— Пива! Это хорошо. Сейчас время обед, закрыто всё, погуляй пока, потом сходим, — Леонид Семёнович расставлял фигуры. — Ну что, Стёпа, отыгрываться будешь?"},{"kind":"paragraph","text":"В обед небо синее, где-то из открытого окна музыка играет. Женщина вешает на верёвку простыни, вокруг неё мальчик ездит на трёхколесном велосипеде. В песочнице девочка учит пьяного дядю Колю делать куличи из песка. У дороги мальчик в пыли машину рисует палкой, а девочка сандаликом стирает. На автомобильной покрышке, вкопанной в землю у обочины, сидит мальчик и смотрит на дорогу. Рот у него выпачкан фиолетовым, тютину ел."},{"kind":"paragraph","text":"— Ты чего? — спросил его Саша."},{"kind":"paragraph","text":"— Жду, когда папа из Москвы приедет, — ответил мальчик, глядя на дорогу в Москву."},{"kind":"paragraph","text":"— Он давно уехал?"},{"kind":"paragraph","text":"— Да, вчера утром."},{"kind":"paragraph","text":"— А машина какая?"},{"kind":"paragraph","text":"— Белый МАЗ."},{"kind":"paragraph","text":"— Ну давай вместе подождем."},{"kind":"paragraph","text":"И ждали, проезжали мимо машины, кисло пахло от свалки напротив, сидели мальчики на вкопанных в землю покрышках у въезда во двор и ждали, когда приедет из Москвы папа на белом МАЗе."},{"kind":"paragraph","text":"Встал Саша, не дождавшись, и пошёл по улице, там у низкого забора стояла девочка и смотрела, как плетутся розы по глухой стене старого дома. Саша у неё спросил:"},{"kind":"paragraph","text":"— Хочешь я тебе сорву? — Они же колючие, поранишься. — Ничего, не страшно. На, подержи банку."},{"kind":"paragraph","text":"Саша перелез через низкий забор обернул руку рубашкой и срывал красные цветки. Девочка, рот приоткрыв, смотрела на него, в опущенных руках банку держала."},{"kind":"paragraph","text":"— Ты чего там делаешь, чертенёнок?!"},{"kind":"paragraph","text":"Бабка торопилась, показывала в воздухе костылем, спускаясь с крыльца."},{"kind":"paragraph","text":"— Бабушка, я только три цветка девочке сорву, не кричи!"},{"kind":"paragraph","text":"— Я тебе дам! Как дам сейчас три цветка тебе! Девочка, вон, твоя бежит?"},{"kind":"paragraph","text":"Саша обернулся и увидел, как девочка бежит по улице, банку бросила у забора. Бабушка махнула костылем и крикнула:"},{"kind":"paragraph","text":"— Чего ты встал, догоняй! Зря рвал чтоль?"},{"kind":"paragraph","text":"Саша перепрыгнул через забор и побежал за девочкой. Бабушка вслед ему строго улыбалась."},{"kind":"paragraph","text":"Из-за угла дома смотрела девочка, как Саша за ней бежит, и смеялась, цветы в руке у него. Саша подбежал к девочке и отдал красные цветы."},{"kind":"paragraph","text":"— Спасибо, — сказала девочка. — Зачем банку бросила? — Испугалась бабку. — Бояка ты. Как тебя зовут? — Катя, а тебя? — Саша."},{"kind":"paragraph","text":"Саша тронул рукой в кармане жирные монеты."},{"kind":"paragraph","text":"— Пойдешь со мной в магазин? — Пойду."},{"kind":"paragraph","text":"По пыльной дороге Катя и Саша к белому ларьку идут мимо дерева, сидят на дереве мальчики, другие мальчики бегут к ним через дорогу с автоматами в руках."},{"kind":"paragraph","text":"— Тра-та-та-та, — кричат мальчики, бегущие по дороге, мальчикам, сидящим на дереве."},{"kind":"paragraph","text":"— Тра-та-та та-та-та, — кричат мальчики с дерева бегущим к ним по дороге мальчикам,"},{"kind":"paragraph","text":"— Всё, вы умерли! — кричат мальчики с дороги мальчикам, сидящим на дереве."},{"kind":"paragraph","text":"— Нет, это вы умерли! — кричат с дерева мальчики мальчикам на дороге."},{"kind":"paragraph","text":"— Вы врёте! Мы вас раньше убили!"},{"kind":"paragraph","text":"— Нет мы вас убили, я в вас гранаты кидал!"},{"kind":"paragraph","text":"Саша держал Катю за руку, чтобы она не боялась выстрелов."},{"kind":"paragraph","text":"— Пойдите к Леониду Семёновичу, он точно скажет, кто кого убил, — сказал Саша одному из мальчиков, проходя мимо."},{"kind":"paragraph","text":"У ларька сидели на бордюре два мужика. Вытянув ноги, они оперлись друг о друга плечами, дремали. В ларьке две женщины ругались. Саша с Катей прошли мимо дремавших на бордюре мужиков и заглянули в окошко ларька. Внутри женщина с красным лицом крикнула:"},{"kind":"paragraph","text":"— Чтоб это было в последний раз, ты меня поняла?"},{"kind":"paragraph","text":"Продавщица в бледно голубом фартуке кивнула ей. Женщина с красным лицом вышла из ларька, хлопнув дверью. Молодая продавщица вздохнула и взглянула в окошко."},{"kind":"paragraph","text":"— Здрасьте. Дайте мороженое, — сказал Саша и повернулся к Кате. — Тебе какое?"},{"kind":"paragraph","text":"— Шоколадное, — сказала Катя, не поднимая глаз от цветов в своей руке."},{"kind":"paragraph","text":"— Шоколадное, — сказал Саша продавщице."},{"kind":"paragraph","text":"Женщина подошла к сидящим на бордюре мужчинам и несильно пнула ногой одного. Он вздрогнул и начал вставать. Сидящий рядом мужик повалился на бок и проснулся. Он лежал на асфальте и сонными глазами смотрел вокруг, на злую женщину, на своего товарища, которого женщина держала под руку, на Сашу, покупавшего Кате мороженое."},{"kind":"paragraph","text":"Женщина под руку увела шатавшегося мужика, а лежавший у ларька застонал, вставая. Он подошёл к Кате и погладил её"},{"kind":"paragraph","text":"по голове. Саша обернулся и дал Кате мороженое, посмотрел в воспаленные глаза мужика."},{"kind":"paragraph","text":"— Ты Леонида Семёновича видел сегодня? — Видел в обед, во дворе играл в шахматы. — Я ему вчера проигрался в карты. — Ну и что? Иди отыгрывайся. — Я карты свои где-то потерял. Есть пять рублей? Я верну. — Не надо, я куплю карты, только пойдем вместе, я играть буду. — Это как так? — Ты ж пьяный, как ты играть будешь?"},{"kind":"paragraph","text":"Саша повернулся к окошку и сказал:"},{"kind":"paragraph","text":"— Дайте ещё карты."},{"kind":"paragraph","text":"Саша вытащил жирную монету и положил в окошко."},{"kind":"paragraph","text":"Катя облизывала шоколадное мороженное и смотрела, как Саша с дядей разговаривает."},{"kind":"paragraph","text":"— Кать, погуляй пока, я сейчас поиграю в карты и приду, — сказал Саша."},{"kind":"paragraph","text":"Катя быстро закивала ему в ответ. Когда Саша с дядей уходил, она посмотрела им вслед и заплакала."},{"kind":"paragraph","text":"В глубине двора, за столом в тени цветущих деревьев сидит Леонид Семёнович. Перед ним мальчики толкаются и кричат. Леонид Семёнович слушает их, смотрит в лица мальчиков, улыбается. Саша издали услышал, как Леонид Семёнович ударил ладонью по столу, встал перед мальчиками высокий Леонид Семёнович и громко сказал:"},{"kind":"paragraph","text":"— Бойцы, прекратить базар!"},{"kind":"paragraph","text":"Мальчики замерли и умолкли, испуганно подняли глаза."},{"kind":"paragraph","text":"Леонид Семёнович громко говорил:"},{"kind":"paragraph","text":"— Командиры, постройте свои отряды как положено."},{"kind":"paragraph","text":"Мальчики без суеты встали в две шеренги друг напротив друга и ждали."},{"kind":"paragraph","text":"— Смирно!"},{"kind":"paragraph","text":"Один мальчик смотрел на Леонида Семёновича и ковырял в носу."},{"kind":"paragraph","text":"— По команде «смирно» спины надо выпрямить, животы втянуть, пальцы из носа вытащить, голову вверх поднять. Ещё раз, смирно!"},{"kind":"paragraph","text":"Мальчики вытянулись, подняли головы к зелёным веткам."},{"kind":"paragraph","text":"— Вольно! Командиры, ко мне!"},{"kind":"paragraph","text":"Двое мальчиков постарше вышли из строя к Леониду Семёновичу."},{"kind":"paragraph","text":"— Докладывайте. По очереди, без воплей."},{"kind":"paragraph","text":"— Наш отряд бежал через дорогу и стрелял, их отряд на дереве сидел."},{"kind":"paragraph","text":"— Наш отряд был на дереве и стрелял в них, а я кидал гранатами."},{"kind":"paragraph","text":"Леонид Семёнович смотрел на мальчиков и думал, потом увидел Сашу и мужика, плетущегося следом, сел за стол и сказал:"},{"kind":"paragraph","text":"— Командиры вы, конечно, смелые, но солдат своих беречь нужно. Из того, что вы тут доложили, я понимаю так, что тут никто не победил. В следующий раз ищите где спрятаться сначала, а потом стреляйте, прикрывайте друг друга. И в следующий раз доклад как сегодня, по военному, поняли?"},{"kind":"paragraph","text":"— Хорошо, — сказал кто-то из мальчиков."},{"kind":"paragraph","text":"— Не хорошо, а так точно!"},{"kind":"paragraph","text":"— Так точно! — хором крикнули мальчики."},{"kind":"paragraph","text":"— Молодцы! Командуйте, командиры."},{"kind":"paragraph","text":"Леонид Семёнович улыбался и смотрел, как мальчики разбегаются по двору, мелькают их выгоревшие майки в кустах. За стол сели Саша и мужик. Леонид Семёнович повернулся к ним, улыбался."},{"kind":"paragraph","text":"— Ну что, Коля, отыгрываться?"},{"kind":"paragraph","text":"Коля смотрел хмуро-пьяно. Саша достал новую колоду карт из кармана и положил на стол."},{"kind":"paragraph","text":"— Я за него буду играть."},{"kind":"paragraph","text":"— Сашок, Сашок. Ну хорошо, — Леонид Семёнович взял колоду, вытряхнул карты из пачки, помешал в руках и разбросал себе и Саше."},{"kind":"paragraph","text":"— Ты пива-то купил? — Нет. — Значит, есть на что играть? — Есть."},{"kind":"paragraph","text":"Саша вытащил из кармана горстку монет."},{"kind":"paragraph","text":"— Смотри, какой будет уговор. Играть будем до последних денег. Кто все деньги проиграет, тот..."},{"kind":"paragraph","text":"— Кто выиграет, тот загадывает желание, — сказал Саша."},{"kind":"paragraph","text":"— Это мне нравится, да. Желание! — Леонид Семёнович хлопнул руками и засмеялся."},{"kind":"paragraph","text":"Саша взял карты со стола, развернул их в руке, три короля, дама, девятка, семёрка. Саша посмотрел на Леонида Семёновича."},{"kind":"paragraph","text":"— Только чур не мухлевать."},{"kind":"paragraph","text":"— Я никогда не мухлюю. Да, Коля?"},{"kind":"paragraph","text":"— Не мухлюет, — мотнул головой Коля."},{"kind":"paragraph","text":"Саша забрал три первых кона. Леонид Семёнович хмурился, быстро поглядывал поверх карт во внимательные Сашины глаза."},{"kind":"paragraph","text":"— Сколько у Коли долгу? — Спросил Саша. — Ты играй, я скажу как отыграешь, — ответил Леонид Семёнович. — Коля, ты что, спишь что ли?"},{"kind":"paragraph","text":"Коля лежал на столе, упёршись лбом в руки. Саша наклонился и заглянул ему в лицо."},{"kind":"paragraph","text":"— Спит, — сказал Саша."},{"kind":"paragraph","text":"— Устал, — улыбнулся Леонид Семёнович."},{"kind":"paragraph","text":"Играли, была уже ночь. Саша взял шесть конов. Леонид Семёнович мешал карты в руках и внимательно смотрел, как в темноте блестят у Саши глаза."},{"kind":"paragraph","text":"— Отыграл, даже с лихвой, — сказал Леонид Семёнович, достал из кармана перевязанные шнурком деньги."},{"kind":"paragraph","text":"— Коля! Коль! Просыпайся."},{"kind":"paragraph","text":"Коля поднял голову и посмотрел кругом, ночь."},{"kind":"paragraph","text":"— Чего? — Деньги раздают."},{"kind":"paragraph","text":"Леонид Семёнович подал ему сложенные бумажки. Коля взял, развернул, в темноте сощурился над деньгами."},{"kind":"paragraph","text":"— Да, да, можешь не смотреть так, Сашок всё за тебя отыграл."},{"kind":"paragraph","text":"— Я это, ну, — Коля вылез из-за стола, наощупь искал, куда деньги положить, — пойду, ночь уже."},{"kind":"paragraph","text":"— Да, ты иди, — сказал Леонид Семёнович и посмотрел на Сашу. — Ну что, Сашок, будешь ещё играть?"},{"kind":"paragraph","text":"— Буду."},{"kind":"paragraph","text":"Играли, светало. Леонид Семёнович смеялся, хлопал в ладоши."},{"kind":"paragraph","text":"— Ну что, Сашок, на желание теперь? — Играем, — сказал Саша, насупившись."},{"kind":"paragraph","text":"Сыграли, Леонид Семёнович в руках перебирал колоду и смотрел на Сашу. Саша сопел, нос заложило, ломило переносицу."},{"kind":"paragraph","text":"— Правильно, плакать последнее дело, — сказал Леонид Семёнович. — Загадывай желание, — сказал Саша подломленным голосом. — Успею. Пойдем лучше прогуляемся."},{"kind":"paragraph","text":"Леонид Семёнович сложил карты в коробку, посмотрел на червовую даму, как она держит красный цветок, и надменные у неё губы и глаза."},{"kind":"paragraph","text":"Шёл высокий Леонид Семёнович и Саша рядом, понурив голову, брёл."},{"kind":"paragraph","text":"— Сашок, ты чего носом пашешь? — Леонид Семёнович положил руку на плечо Саше."},{"kind":"paragraph","text":"— Ничего, — пробурчал Саша."},{"kind":"paragraph","text":"— Раз ничего, подними голову, не на расстрел идешь!"},{"kind":"paragraph","text":"Саша поднял глаза и сердито посмотрел. Они шли местами, каких он не видел никогда."},{"kind":"paragraph","text":"— Ты знаешь, где мы идём?"},{"kind":"paragraph","text":"— Нет, я здесь не был."},{"kind":"paragraph","text":"— А я здесь с молодых лет гуляю. Когда-то я по этим местам проехал с сестрой друга. Никак теперь не хочу уезжать, хорошо здесь, до моря недалеко."},{"kind":"paragraph","text":"— До какого моря, нету тут моря."},{"kind":"paragraph","text":"— Ты не видел моря, а оно здесь было и сейчас ещё есть. Показать?"},{"kind":"paragraph","text":"— Покажи."},{"kind":"paragraph","text":"— Пойдем, тут недалеко."},{"kind":"paragraph","text":"— А что с твоим другом стало, он не поехал с сестрой и с тобой?"},{"kind":"paragraph","text":"— Нет, не поехал. Он пропал куда-то, убили его, наверное."},{"kind":"paragraph","text":"— Почему его убили?"},{"kind":"paragraph","text":"— Он был бандит. Он сам всех убивал, вот и они его убили."},{"kind":"paragraph","text":"— А ты тоже был бандит?"},{"kind":"paragraph","text":"— Я тоже был."},{"kind":"paragraph","text":"— И убивал?"},{"kind":"paragraph","text":"— Убивал, мы все убивали."},{"kind":"paragraph","text":"— Я никого не убивал."},{"kind":"paragraph","text":"— Лягушек не убивал? Пауков, жуков?"},{"kind":"paragraph","text":"— Убивал, но это не считается, они ведь не понимают, что живут."},{"kind":"paragraph","text":"— Это хорошо, что не понимают."},{"kind":"paragraph","text":"Над пыльными дорогами солнце, у дороги домик, дверь заколочена, на двери белой краской написано: «Украдёшь себе на могильную оградку». Вдали видны три высоких дворца, через все холмы по дорогам до самого конца к ним идти."},{"kind":"paragraph","text":"— Что это за дома вдалеке?"},{"kind":"paragraph","text":"— Это дворцы древние, их ещё не достроили."},{"kind":"paragraph","text":"— Их же разрушили уже очень давно."},{"kind":"paragraph","text":"— Их и достроить не успели, а уже разрушили."},{"kind":"paragraph","text":"— Это же в войну ещё?"},{"kind":"paragraph","text":"— Да, в войну."},{"kind":"paragraph","text":"— Ты в той войне воевал?"},{"kind":"paragraph","text":"— Нет, я только приехал, когда закончилась война. Теперь уже забыли войну, только пацаны во дворе ещё помнят, играют, стреляют друг друга."},{"kind":"paragraph","text":"Саша ничего ему не ответил. Он обернулся, но города не было видно, посмотрел вдаль, ничего нет вдали, только воздух."},{"kind":"paragraph","text":"— Из чего сделано небо, Леонид Семёнович?"},{"kind":"paragraph","text":"— Небо сделано из воздуха."},{"kind":"paragraph","text":"— Если мы с тобой будем быстро дышать, то сможем всё небо сдышать?"},{"kind":"paragraph","text":"— Ты и без меня справишься, всё небо сдышать — это не сказать что трудно, это как море переплыть."},{"kind":"paragraph","text":"— А где море?"},{"kind":"paragraph","text":"— Мимо тех дворцов пройдем, потом на гору поднимемся, и там море будет."},{"kind":"paragraph","text":"— Мы ведь долго уже идём?"},{"kind":"paragraph","text":"— Не знаю, у тебя часы есть?"},{"kind":"paragraph","text":"— У меня нет."},{"kind":"paragraph","text":"— У меня тоже. Я часам не верю, не так, как надо, время считают."},{"kind":"paragraph","text":"— А как узнать, как правильно считать? — Этому долго учиться, это трудно. Нетрудно всё небо сдышать, а понять, как время считается, сложно."},{"kind":"paragraph","text":"Мимо дворцов шли Саша и Леонид Семёнович, белые глыбы отвалились одна от другой, колонны из белого камня стояли высоко, крошились камни от солнца и от ветра, от зим и ночей. Деревья росли на верхах колонн, сквозь белые глыбы свисали корни."},{"kind":"paragraph","text":"— Как деревья на домах растут?"},{"kind":"paragraph","text":"— А дети как в домах растут? Так же и деревья."},{"kind":"paragraph","text":"У дороги, в высокой траве лежал и смеялся человек, не видно было, где он лежит, но слышно, смеётся. Леонид Семёнович тоже засмеялся и пошёл в высокой траве к человеку, наклонился над ним и долго смотрел, смеялся. Саша стоял и слышал, как тихо на дорогах и только смеются мужчины."},{"kind":"paragraph","text":"— Он уснул и смеётся, — сказал Леонид Семёнович, вышел из высокой травы и обирал штаны от прицепившегося репея."},{"kind":"paragraph","text":"— Почему он здесь спит и смеётся?"},{"kind":"paragraph","text":"— Тепло, хорошо здесь, — Леонид Семёнович упёрся ладонями в спину и вытянулся, — но здесь спать нельзя, уснешь вот, как он, и так хорошо будет, что уже и не проснешься."},{"kind":"paragraph","text":"Поднимались Леонид Семёнович и Саша на высокий холм, и ветер поднимался. На холме старые каменоломни, порода пустая. Влез по камням Саша, смотрел, как вода разлилась от берегов до берегов, как птицы над водой летят, какой свет над водой. Леонид Семёнович идёт по заросшей тропе к высокому каменному мосту через воду. Обернулся к Саше и зовёт, машет рукой."},{"kind":"paragraph","text":"Саша спустился с камней и пошёл следом, Леонид Семёнович далеко на мосту стоит, наклонился к парапету, смотрит в воду с моста высокого."},{"kind":"paragraph","text":"— Это мост через всё море? — Не знаю, я до того берега не ходил. — А давай дойдем, Леонид Семёнович? — Пойдём, мне самому интересно."},{"kind":"paragraph","text":"Долго по мосту шли Саша и Леонид Семёнович, ветер им воротники поднимал, внизу далеко волны били в каменные сваи. От солнца и воды без края глаза утомились, Леонид Семёнович прищурился и приложил руку к глазам."},{"kind":"paragraph","text":"— Дошли, там уже конец. — Пойдем, пойдем, — Саша толкнул Леонида Семёновича. — Пойдем, — засмеялся Леонид Семёнович."},{"kind":"paragraph","text":"У самого края моста остановились, а впереди всё море, и не видно берега, от которого они сюда пришли, не видно и другого берега, куда мост не довёл."},{"kind":"paragraph","text":"— Тоже в войну разрушили, наверное, — сказал Саша, глядя на последнюю каменную глыбу, обтёсанную бурями."},{"kind":"paragraph","text":"— Этот мост строили тогда же, когда и те дворцы, что мы прошли, очень-очень давно. Война началась, и с тех пор не достроили."},{"kind":"paragraph","text":"Саша сел на самом краю последнего камня и свесил ноги над морем. Леонид Семёнович стоял за ним."},{"kind":"paragraph","text":"— Не страшно, Сашок? — Неа."},{"kind":"paragraph","text":"— Тогда желание. — Загадывай. — Прыгни с моста."},{"kind":"paragraph","text":"Саша поднял глаза на Леонида Семёновича, смотрел без страха. Леонид Семёнович улыбался."},{"kind":"paragraph","text":"— Так нечестно, — тихо сказал Саша."},{"kind":"paragraph","text":"— Очень честно, карточные долги нужно выполнять."},{"kind":"paragraph","text":"— Но я же умру, — сказал Саша, руками держал холодный каменный мост."},{"kind":"paragraph","text":"— Ты же любопытный. Не интересно тебе разве узнать, как это, умереть?"},{"kind":"paragraph","text":"Саша смотрел, как волны разбиваются об мост."},{"kind":"paragraph","text":"— Там Катя у ларька сидит, я ей обещал, что приду за ней."},{"kind":"paragraph","text":"— Ну и чего ты тогда расселся? Пойдем Катю забирать! — крикнул морю Леонид Семёнович и засмеялся."},{"kind":"paragraph","text":"Саша встал, и пошли они с Леонидом Семёновичем."},{"kind":"paragraph","text":"У ларька собака зарычала на них."},{"kind":"paragraph","text":"— Дурак ты, — сказал псу Леонид Семёнович и погладил по голове."},{"kind":"paragraph","text":"Саша обернулся на него, подходя к окошку ларька."},{"kind":"paragraph","text":"— М, м, — Леонид Семёнович искал в кармане. — На. — Леонид Семёнович подал Саше колоду карт. Саша посмотрел на червовую даму, как она держит красный цветок, и надменные у неё губы и глаза."},{"kind":"paragraph","text":"— Здрасьте, — сказала продавщица."},{"kind":"paragraph","text":"— Здравствуй, Катя, — сказал Саша."},{"kind":"paragraph","text":"— Здравствуй, здравствуй."},{"kind":"paragraph","text":"— Я Саша."},{"kind":"paragraph","text":"— Я рада, что ты Саша."},{"kind":"paragraph","text":"— Ты меня не помнишь?"},{"kind":"paragraph","text":"— Вроде бы нет, я вас всех помню, а тебя вот что-то никак."},{"kind":"paragraph","text":"— Помнишь, я тебе цветы у бабы Веры в палисаднике рвал, она вышла с костылем и ты испугалась? А потом мы в этот ларёк пошли, потом я ушёл в карты играть, а ты меня ждала?"},{"kind":"paragraph","text":"Продавщица долго посмотрела на Сашу."},{"kind":"paragraph","text":"— Помню, Сашенька. Где же ты был? Говорили, в тюрьме."},{"kind":"paragraph","text":"— Нет, я..."},{"kind":"paragraph","text":"Леонид Семёнович показал Саше рукой, и прикрыл глаза, упёршись спиной о ларёк. Продавщица посмотрела на кнопки кассы, на булочки в целлофановых пакетах, на половинку конфеты, лежащую на блестящей обертке рядом с пустой потемневшей от чая кружкой."},{"kind":"paragraph","text":"— Пойдём, — сказала продавщица, снимая фартук."},{"kind":"paragraph","text":"Она вышла из ларька и посмотрела на Леонида Семёновича, опёршегося спиной на металлическую стену. Катя потрогала его за руку, спросила:"},{"kind":"paragraph","text":"— Деда, ты что, тебе плохо?"},{"kind":"paragraph","text":"Леонид Семёнович приоткрыл глаза, махнул рукой и снова закрыл глаза. Когда Катя отвернулась, Леонид Семёнович подмигнул Саше и улыбнулся. Саша кивнул ему в ответ и пошёл с Катей вверх по улице."},{"kind":"paragraph","text":"— Пойдем, я тебе сына покажу, — сказала Катя."},{"kind":"paragraph","text":"У входа в школу, на треснувших ступеньках стоял охранник в чёрной куртке."},{"kind":"paragraph","text":"— Здрасьте, — сказал охранник. — Здрасьте, — сказала Катя, и Саша «Здрасьте» сказал."},{"kind":"paragraph","text":"По коридору налево, дверь на кухню открыта, из столовой обедом пахнет, учительская справа и медпункт, пахнет хлоркой, в конце коридора, под лестницей дверь, слышно, как там баян играет."},{"kind":"paragraph","text":"— Пение у них, — шепнула Катя, быстро заглянула в приоткрытую дверь, повернулась к Саше, — мой за первой партой в центре, поёт, — улыбнулась."},{"kind":"paragraph","text":"Саша заглянул в дверь. Перед доской сидит учитель с баяном."},{"kind":"paragraph","text":"— А сейчас мы с вами споём песню, которую мы учили в прошлой четверти, все её помнят? — Да! Которая была в гостье из будущего! — Да, она самая. И-и-и раз! — Слышу голос из прекрасного далёка… — Хорошо! — …Голос утренний в серебряной росе… — Чуть медленнее! — …Слышу голос, и манящая дорога… — Погромче, девочки! — …Кружит голову, как в детстве карусель!… — Давайте ещё раз, сначала. И-и-и раз!"}]'::jsonb, '2020-12-30T12:00:00.000Z'
) ON CONFLICT (slug) DO UPDATE SET
  title=EXCLUDED.title, author_id=EXCLUDED.author_id, cover_path=EXCLUDED.cover_path,
  cover_blur=EXCLUDED.cover_blur, cover_width=EXCLUDED.cover_width, cover_height=EXCLUDED.cover_height,
  excerpt=EXCLUDED.excerpt, content_blocks=EXCLUDED.content_blocks, published_at=EXCLUDED.published_at;

INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd1-uscherb', 'Ущерб',
  (SELECT id FROM "Authors" WHERE name = 'Георгий Панкратов' ORDER BY id LIMIT 1),
  'mrd1/mrd1-uscherb.jpg', 'data:image/jpeg;base64,', 947, 670,
  'Вадим жил с Вероникой уже седьмой год. Не расписался — и так нормально. В последние месяцы сидел без дела — был отделочником, но не котировался слишком высоко. Работу не предлагали. Так, подхалтуривал иногда: в его тридц', '[{"kind":"image","path":"mrd1/mrd1-uscherb.jpg","caption":null},{"kind":"paragraph","text":"Вадим жил с Вероникой уже седьмой год. Не расписался — и так нормально. В последние месяцы сидел без дела — был отделочником, но не котировался слишком высоко. Работу не предлагали. Так, подхалтуривал иногда: в его тридцать восемь поздно было искать что-то новое, рыпаться. В общем, жил в ожидании лучших времён."},{"kind":"paragraph","text":"Иногда что-то делал по дому, встречал, провожал жену. Та крутилась в офисе. О работе жены он не знал ничего, и ему было неинтересно. Отношения с Вероникой были нормальными — не в том смысле, что без проблем, а в том, что без искорки: ну, не искрилось между ними после стольких лет. Но и Вадим, и Вероника поступили так, как поступа-"},{"kind":"paragraph","text":"ют все: забили на это. Что же, расходиться теперь, если нет искорки?"},{"kind":"paragraph","text":"Развлекаться Вадим не умел, а у жены не было времени. Иногда гуляли в ближайшем парке. Вадим стоял на балконе и курил, осматривая двор, Вероника осторожно открывала дверь и предлагала: «Пойдём?». «Ну, пошли, чё», — отвечал Вадим, и они выходили на улицу. Приближался Новый год. Хоть и через месяц только, а думать уже надо: как отметить, где деньги брать, сколько… Да и просто можно было фантазировать, представляя, как на несколько долгих и сонных дней всё вокруг станет хорошо. Сказочно."},{"kind":"paragraph","text":"— А, вспомнила, — сказала Вероника по дороге. — Надо в офис смотаться за документами. Завтра ж к этой… — она выругалась, — через весь город переться. Вставать рано. А я их забыла, вот дура!"},{"kind":"paragraph","text":"— Да езжай ты с утра, — вяло возразил Вадим."},{"kind":"paragraph","text":"— Ну Вадим, ну чё ты… Это мне в пять утра вставать надо. Как маленький. На автобусе доедем — полчаса и свободны."},{"kind":"paragraph","text":"— Ладно, поехали, — безучастно сказал Вадим, и они отправились на остановку. Вадим закурил."},{"kind":"paragraph","text":"— Вот подарю тебе на Новый год никотиновый пластырь, — шутила Вероника."},{"kind":"paragraph","text":"— Не-не-не! — бурно возразил Вадим и пояснил, где он видел такие подарки."},{"kind":"paragraph","text":"— А вообще, давай ничего не дарить друг другу, — предложила Вероника. — Сэкономим. Съездим к маме, погостим…"},{"kind":"paragraph","text":"— Ой, на фиг надо, — скривился Вадим, — к маме твоей… Давай у нас лучше. Фейерверки позапускаем."},{"kind":"paragraph","text":"— Ага, — Вероника поднесла руки к лицу и шумно выдохнула в них, а потом улыбнулась, взглянула на Вадима добрым взглядом. — Скорей бы."},{"kind":"paragraph","text":"— Скорей бы автобус, — буркнул Вадим. — Хабец выкину."},{"kind":"paragraph","text":"Подходя к урне, Вадим краем глаза заметил, как грузовик на противоположной стороне улицы стал разворачиваться — остановка находилась на перекрёстке их двухполосной улицы не с переулком даже, а с узенькой асфальтовой дорожкой, по которой завозили продукцию в универсам."},{"kind":"paragraph","text":"«Ну и как он тут проедет, дятел?» — подумал Вадим, и вдруг эту мысль перебила другая, шальная и страшная. Его обдало холодом, словно кто-то швырнул в лицо снега, и он обернулся. Пытаясь уйти от удара, прямо в остановку неслась чёрная иномарка. И в этот же миг всё вокруг стихло, только кружились в жёлтом свете фонаря снежинки."},{"kind":"paragraph","text":"Вадим повёл себя странно: он не бросился к остановке сразу же, не закричал — он закрыл глаза, чтобы ничего не видеть, и долго стоял так. Когда наконец двинулся к месту, вокруг уже толпились люди, кто-то суетился и причитал, кто-то щупал пульс. Жена лежала как живая, только мёртвая. Немного крови на висках — и всё. И в руке сумка."},{"kind":"paragraph","text":"Неподалеку остановилась разбитая иномарка. За рулём сидел крупный человек в тонких очках, бритый наголо, в сером пальто. Он смотрел прямо перед собой и не шевелился."},{"kind":"paragraph","text":"— Я убью тебя, сука! — заорал Вадим. Стучал по стеклу кулаками, затем водитель опустил стекло. — Что ж ты сделал-то?!"},{"kind":"paragraph","text":"Потом были похороны. Точнее, была кремация, но русский человек не скажет «был на кремации», он всё равно скажет «на похоронах». Народу было немного — девчонки с работы да её родители. Они Вадима не любили. Жил он с женой,"},{"kind":"paragraph","text":"правда, в своей квартире, так что съезжать никуда не пришлось. Но кроме квартирки, доставшейся от родных, у него ничего не осталось."},{"kind":"paragraph","text":"Началось разбирательство. Вадим ходил в суд неохотно — для дачи показаний, пару раз. Уже в первый день мужчина из иномарки высказал желание поговорить. Они зашли в пустой зал и долго сидели, молчали. А потом водитель резко, безо всяких предисловий, предложил ему взять миллион."},{"kind":"paragraph","text":"— Ты что же, сука, откупиться хочешь?! — взревел Вадим."},{"kind":"paragraph","text":"— Видишь, — спокойно сказал водитель, — я не то чтобы очень богат, но... Я не зверь, так вышло случайно. Но перед Богом я всё равно виноват... Я просто хочу помочь. Это не то чтобы моральный ущерб… Да, никакими деньгами… Но это единственное, что я могу сделать."},{"kind":"paragraph","text":"— Пошёл ты! — крикнул Вадим, направляясь к выходу. — Засунь себе в жопу, понял?"},{"kind":"paragraph","text":"— Придёшь в следующий раз, сообщи реквизиты, — устало сказал водитель."},{"kind":"paragraph","text":"«Ущерб! — думал Вадим дома. — Ишь ты!». Ему не нравилось это слово: так его дразнили школе. Кликуха такая была, у всех разные. У него вот Ущерб. Вспоминать было неприятно."},{"kind":"paragraph","text":"Когда снова пришёл в суд — дал номер счёта, и в тот же день ему перевели миллион."},{"kind":"paragraph","text":"Потом он весь вечер пялился в ящик. Думал мучительно: «Как потратить деньги, чтобы с умом, или вложить во чтото. Но во что?». И ещё подумал с горечью: «Как она была бы рада! Перед самым Новым годом — миллион!»."},{"kind":"paragraph","text":"Сразу постановил для себя: не бухать. Ни в коем случае. Но в первый же вечер навалилась такая тяжесть, что оставаться трезвым было невыносимо. Он отправился в бар и пропил двенадцать тысяч."},{"kind":"paragraph","text":"«Ничего, — думал, — скоро выйду на работу. Отработаю, доложу обратно. Буду считать, что свои пропил. Считай, взял в долг. У мёртвой жены…» От тоскливых мыслей хотелось напиться сильнее, чтобы забыть их."},{"kind":"paragraph","text":"Но наутро навалилось такое похмелье, что Вадим понял: он может банально сдохнуть. Башка разорвётся на части."},{"kind":"paragraph","text":"Так он провёл две недели. Иногда звал приятелей. Иногда ночевал дома, подолгу перед сном глядел на её фото, что стояло на подоконнике возле тощего цветка. Было тошно."},{"kind":"paragraph","text":"Потом была Лига чемпионов. Однажды, смотря под пивко матч, Вадим увидел в кадре красивых болельщиц. Вдруг почувствовал сильное желание — и просто никак не смог справиться. Покопался на сайтах и вызвонил двух женщин. Вадиму нужны были две. Полночи занимался непотребствами, пока хватало сил. Бросив распалённый страстью взгляд на подоконник, увидел её фото. Подошёл, отвернул."},{"kind":"paragraph","text":"Назавтра Вадим осознал, что пить больше нельзя. Весь день проклинал судьбу, вечером подсчитал деньги: семьсот тысяч, не так плохо."},{"kind":"paragraph","text":"Новый год был совсем скоро. Было ужасно встречать его без Вероники, но он решил сделать подарок себе — больше всё равно некому. А заодно и ей: может, увидит с небес, порадуется. Купил новый диван, плазму, мощный компьютер, остеклил"},{"kind":"paragraph","text":"балкон — купил материалы, вызвал рабочих. Подключил, наконец, кабельное телевидение — Вероника давно хотела. Ещё четыреста тысяч осталось."},{"kind":"paragraph","text":"После праздников приезжали её родители, поразились переменам. Хотели забрать вещи дочери: что-то из одежды, белья, мелочёвку, но Вадим пожал плечами. «А я всё выкинул», — сказал он простодушно. Чтоб отстали, пошёл в комнату, отсчитал сто… Потом передумал — пятьдесят тысяч. Триста пятьдесят положил в ящик, рядом с паспортом и ИНН."},{"kind":"paragraph","text":"А потом Вадим обнаружил, что совсем нет одежды, обуви — и отправился в магазин. По дороге обратно купил огромную тележку хороших продуктов. Еле дотащил. Пока тащил, подумал, что неплохо бы автомобиль. Да только вот какой? На двести семьдесят тысяч особо не повыбираешь."},{"kind":"paragraph","text":"Сговорился с мужиком на сайте «Авито». Мужик оказался нормальный, работяга, поняли друг друга быстро."},{"kind":"paragraph","text":"— Нормальная? — спросил Вадим, кивая на машину. — Нормальная, — кивнул мужик."},{"kind":"paragraph","text":"Ударили по рукам. Осталось ещё двадцать тысяч и несколько сотен. Доехав до дома, Вадим отправился в ночной ларёк и взял пивка. Не торопясь, зашёл в подъезд, выругался, как всегда, там было темно. Вспомнил, как Вероника просила вставить лампочку. «Да че её ставить! Сразу же упрут»."},{"kind":"paragraph","text":"В темноте сверкнули огоньки сигарет — и пара быстрых ударов свалила его на пол. Вадим не успел ничего понять. Последнее, что слышал, — гнусавый голос:"},{"kind":"paragraph","text":"— Двадцак и мелочь. — Нормально! — ответил второй, такой же."},{"kind":"paragraph","text":"Очнувшись, побрёл домой, умылся, упал на диван, отоспался."},{"kind":"paragraph","text":"Начиналась весна. Деньги кончились, даже те, что удалось выручить с продажи плазмы и компа. Спустился к почтовым ящикам, достал газету, нашёл номер. Позвонил."},{"kind":"paragraph","text":"— Ребят, отделочники нужны? Нормальный, много не пью."},{"kind":"paragraph","text":"На следующий день пришёл на объект — квартиру с множеством окон, просторной кухней, несколькими комнатами и двумя — Вадим присвистнул — туалетами. Прораб обрисовал задачу, познакомил с другими работягами. «Мужики вроде нормальные», — решил Вадим. Оставалось дождаться босса."},{"kind":"paragraph","text":"Когда в квартиру вошёл человек в сером пальто, бритый наголо, в тонких очках, Вадим уже не чувствовал ничего. Он не вскочил с места, не бросился с криком: «Ты, сука!». Нужны были деньги, нужно было работать, жить."},{"kind":"paragraph","text":"Они только обменялись взглядами — короткими, выразительными."},{"kind":"paragraph","text":"— Смотри сам, — выдохнул мужчина. — Ничего, — шмыгнул Вадим. — Нормально. — Ну ладно, — сказал мужчина. — Работай."},{"kind":"paragraph","text":"Прораб на будущей кухне уже дожидался его: нужно было решить по деньгам."},{"kind":"paragraph","text":"Рассказ из сборника «Российское время», Чтиво, 2019"}]'::jsonb, '2020-12-30T12:00:00.000Z'
) ON CONFLICT (slug) DO UPDATE SET
  title=EXCLUDED.title, author_id=EXCLUDED.author_id, cover_path=EXCLUDED.cover_path,
  cover_blur=EXCLUDED.cover_blur, cover_width=EXCLUDED.cover_width, cover_height=EXCLUDED.cover_height,
  excerpt=EXCLUDED.excerpt, content_blocks=EXCLUDED.content_blocks, published_at=EXCLUDED.published_at;

INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd1-spokoynoy-nochi', 'Спокойной ночи',
  (SELECT id FROM "Authors" WHERE name = 'Артём Северский' ORDER BY id LIMIT 1),
  'mrd1/mrd1-spokoynoy-nochi.jpg', 'data:image/jpeg;base64,', 947, 710,
  'В почтовом ящике Лена нашла письмо, адресованное женщине по имени Нина.', '[{"kind":"image","path":"mrd1/mrd1-spokoynoy-nochi.jpg","caption":null},{"kind":"paragraph","text":"В почтовом ящике Лена нашла письмо, адресованное женщине по имени Нина."},{"kind":"paragraph","text":"«Я такую не знаю, хотя живу здесь пять лет», — подумала."},{"kind":"paragraph","text":"Вернувшись из магазина, Лена положила пакет с продуктами на стул и вынула письмо из кармана. Приди оно по ошибке, адрес был бы другим — но указан верно."},{"kind":"paragraph","text":"Осмотрев конверт со всех сторон, Лена подняла его, чтобы солнечные лучи помогли ей узнать, что внутри."},{"kind":"paragraph","text":"Обыкновенный листок бумаги."},{"kind":"paragraph","text":"— Мам, ты не знаешь какую-нибудь Нину? — спросила Лена, входя в большую комнату."},{"kind":"paragraph","text":"Мама сидела за столом с очками на носу и читала газету. Телевизор работал почти без звука."},{"kind":"paragraph","text":"— Не знаю. В нашем подъезде таких нет, — она взяла конверт и придирчиво осмотрела. — Адрес наш. Но отправитель… П. Что это значит?"},{"kind":"paragraph","text":"— Вот именно, — сказала Лена, кусая губы. Непременно хотелось узнать, кто эта женщина и таинственный П."},{"kind":"paragraph","text":"Возвращая конверт, мама сказала: — Почерк мужской, — Лена кивнула, — могу поспрашивать. — Нет. Не нужно."},{"kind":"paragraph","text":"Вернулась на кухню. Раскладывая продукты в холодильнике, думала о письме. Конверт, лежащий в кармане, становился как будто тяжелее с каждой минутой."},{"kind":"paragraph","text":"— А прошлые хозяева, у которых мы квартиру купили? — спросила Лена громко, чтобы мама услышала."},{"kind":"paragraph","text":"— Нет никакой Нины."},{"kind":"paragraph","text":"— Понятно."},{"kind":"paragraph","text":"Письмо тревожило, но в то же время обладание им доставляло Лене удовольствие. Точно маленькая девочка, зарывшая секретик в лесу, она предвкушала нечто такое, что и сама не могла описать."},{"kind":"paragraph","text":"Закрыв дверь спальни, Лена села на кровать и вытянула ноги. Письмо пристроила на коленях."},{"kind":"paragraph","text":"Думала: «Наверное, там что-то необычное. Этот П., должно быть, зовёт куда-то неизвестную Нину, обещает иную жизнь, любит»."},{"kind":"paragraph","text":"Лена помассировала левый висок. Пока нерешительно, но невидимка уже начал забивать туда гвоздь."},{"kind":"paragraph","text":"Были два человека, их связывала общая история, состоящая из множества мелких событий, которые тесно сплетались меж собой. Но где-то в этом сплетении случился разрыв. Лене грустно было думать, что Нина и П. расстались."},{"kind":"paragraph","text":"Поглаживая конверт, она поняла, что сопереживает им, словно героям любимого фильма. Её фантазия выстраивала замысловатые сюжетные ходы и конструировала финал. Лена старалась делать его счастливым."},{"kind":"paragraph","text":"Вечером о письме не говорили. Мама точно забыла о нём."},{"kind":"paragraph","text":"Поужинали, Лена мыла посуду. Поставив тарелки в сушилку, она приняла окончательное решение вскрыть конверт."},{"kind":"paragraph","text":"Нины здесь нет, а если она когда-нибудь появится, чтобы потребовать письмо, Лена, конечно, отдаст и принесёт извинения. Только этого никогда не случится. Жизнь не кино."},{"kind":"paragraph","text":"Расстелив постель, Лена сунула ноги под одеяло. Письмо было у неё в руках, бумага жгла пальцы."},{"kind":"paragraph","text":"«Любимая моя Нина."},{"kind":"paragraph","text":"Надежды, что ты прочтешь письмо, нет. Ты выбро-"},{"kind":"paragraph","text":"сишь его сразу, как только увидишь. Но что делать? —"},{"kind":"paragraph","text":"ты не отвечаешь на звонки и смс. Если бы мог, то при-"},{"kind":"paragraph","text":"ехал, тогда бы мы поговорили. Но я не могу. Может"},{"kind":"paragraph","text":"быть, ты вообще мертва и поэтому не можешь отве-"},{"kind":"paragraph","text":"тить. Мне известно: твоя мама умерла год назад от ин-"},{"kind":"paragraph","text":"фаркта. Жаль. Ответь — как ты?!"},{"kind":"paragraph","text":"Это моё пятое письмо, буду писать, пока… впрочем,"},{"kind":"paragraph","text":"загадывать бессмысленно."},{"kind":"paragraph","text":"Прости меня за всё, что я сделал тебе, за всю причи-"},{"kind":"paragraph","text":"ненную боль. Мне стыдно за свое поведение и за тру-"},{"kind":"paragraph","text":"сость. Мне казалось, если уйду, нам обоим станет легче,"},{"kind":"paragraph","text":"хотя не сразу, но станет. Нина, прости! Прости! Я при-"},{"kind":"paragraph","text":"еду, как смогу. Надеюсь, ты всё ещё там. Надеюсь."},{"kind":"paragraph","text":"Твой Павел»."},{"kind":"paragraph","text":"Аккуратно положила письмо обратно в конверт и бросила его на пол."},{"kind":"paragraph","text":"Сильно заболела голова, висок ломило, на краю зрения прыгали оранжевые точки."},{"kind":"paragraph","text":"Выключив свет, легла под одеяло, пережидая в темноте, когда закончится приступ. Так погрузилась в дрёму. Боль утихла минут через сорок."},{"kind":"paragraph","text":"Зажгла свет, посидела, глядя на лежащее на полу письмо."},{"kind":"paragraph","text":"«Нина жила здесь, теперь её нет»."},{"kind":"paragraph","text":"Захотелось пить. Встала и пошла босиком из комнаты. Квартира была тихой, время от времени вздрагивал на кухне холо-"},{"kind":"paragraph","text":"дильник. Открыв его, налила полстакана молока, выпила, стоя возле окна. В полночь стало темно, жёлтые комья света таращились со столбов."},{"kind":"paragraph","text":"Поставив на стол стакан, отправилась обратным путем, но замерла на пороге большой комнаты."},{"kind":"paragraph","text":"«Пахнет пустотой, — подумала, — здесь давно нет человеческого тепла»."},{"kind":"paragraph","text":"Квартира напоминала пустую коробку из-под обуви."},{"kind":"paragraph","text":"Дверь маминой комнаты приоткрыта на ширину ладони. Подошла к ней, толкнула, держась за ручку, и включила свет."},{"kind":"paragraph","text":"Заправленная кровать, задернутые шторы, пыль на предметах. Мамы не стало год назад. Павел как-то узнал. Кто сказал ему?"},{"kind":"paragraph","text":"Неважно. Выяснять что-либо или отвечать на его письма она всё равно не будет."},{"kind":"paragraph","text":"Лена ушла в свою комнату, укрылась одеялом и выключила свет."},{"kind":"paragraph","text":"Спокойной ночи."}]'::jsonb, '2020-12-30T12:00:00.000Z'
) ON CONFLICT (slug) DO UPDATE SET
  title=EXCLUDED.title, author_id=EXCLUDED.author_id, cover_path=EXCLUDED.cover_path,
  cover_blur=EXCLUDED.cover_blur, cover_width=EXCLUDED.cover_width, cover_height=EXCLUDED.cover_height,
  excerpt=EXCLUDED.excerpt, content_blocks=EXCLUDED.content_blocks, published_at=EXCLUDED.published_at;

INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd1-chisto-osmanskoe-ubiystvo', 'Чисто османское убийство',
  (SELECT id FROM "Authors" WHERE name = 'Наиль Абдуллазаде' ORDER BY id LIMIT 1),
  'mrd1/mrd1-chisto-osmanskoe-ubiystvo.jpg', 'data:image/jpeg;base64,', 711, 711,
  'Когда за трабзонским пашой Нусрет-беем послали из Стамбула шёлковый шнурок, он уже обо всём догадался, и по его спине от страха побежал ручейком холодный пот Паша, который прошёл войны и на Востоке, и на Западе, не боялс', '[{"kind":"image","path":"mrd1/mrd1-chisto-osmanskoe-ubiystvo.jpg","caption":null},{"kind":"paragraph","text":"Когда за трабзонским пашой Нусрет-беем послали из Стамбула шёлковый шнурок, он уже обо всём догадался, и по его спине от страха побежал ручейком холодный пот Паша, который прошёл войны и на Востоке, и на Западе, не боялся умереть, он боялся быть задушенным, как собака. Нусрет-бей, не задерживаясь ни секунды, собрал самое необходимое и, не дожидаясь вечернего намаза, сбежал в сторону границы с Ираном. Перед тем, как навсегда покинуть Трабзон, свой дом и берег Чёрного моря, он сбрил усы, переоделся в одежду своего слуги, но не отказался от своего коня, который ещё до вечернего намаза следующего дня уже привез пашу к границе двух царств. Пока он скакал на Восток, с него ветром сдувало его прошлую жизнь. Его лицо за ночь изменилось так, что в нём не оста-"},{"kind":"paragraph","text":"лось ни намека на суровость грозного паши. Его руки к утру ослабели настолько, что разучились держать саблю и ятаган, он научился сутулиться, а лицо бывшего паши научилось заискивающе улыбаться. Он снял с себя гордость и бесстрашие, как одежду, и напялил на себя лохмотья лицемерия и унижения. Как только Нусрет-бей спешился, его верный конь упал и испустил дух. Так бывший паша лишился последнего, что у него оставалось от самого себя настоящего."},{"kind":"paragraph","text":"Нусрет-паша был не молод и не стар, а в том возрасте, когда время перестает течь быстро и начинает наполняться мыслями и снами. С усами он был похож на льва, а без усов — на шакала. Нусрет-бей не знал, за что его приказали убить. Он верно, как пёс, служил султану и Великой Османской династии. «Моё богатство и моя слава не уберегли меня ни от зависти, ни от клеветы», — думал беглец и печально вздыхал. Чтобы не быть узнанным, он стал сутулиться, научился заикаться. За бакшиш в десять акче ему помогли пересечь границу и показали дорогу в Тебриз. Денег у него оставалось только на то, чтобы сесть на осла и несколько раз переночевать в караван-сарае."},{"kind":"paragraph","text":"«Сесть на осла — позор, слезть с осла — двойной позор», — подумал Нусрет-бей и пошёл в Тебриз пешком, ведя рядом с собой ослика с грустной мордочкой. До того, как паша пересёк границу, рядом с ним в воздухе летели запахи тимьяна, красного перца и кориандра. А после того, как он оказался в Иране, за ним по пятам следовали запахи барбариса, корицы и куркумы. Нусрет-паша шёл так же быстро, как когда-то его теперь уже мертвый конь, о котором он и не вспоминал. По дороге он придумывал себе новые имена, похожие на персидские. В этой части Ирана говорили на туркоманском языке, поэтому если его и не принимали за своего, то и чужим не считали. Наконец, дойдя до Тебриза, он подобрал на улице новое"},{"kind":"paragraph","text":"имя, Хасан. Денег у Хасана осталось только на то, чтобы несколько раз пообедать."},{"kind":"paragraph","text":"В то время пока бывший паша бежал на Восток, в самом Трабзоне его искали по всему городу и окрестностям, а не найдя, отправили в Стамбул во дворец Топкапы депешу о его побеге. Через четыре дня пришёл ответ, и шёлковый шнурок не остался без применения. Тот, кто упустил попавшего в опалу пашу, тот на себя его и примерил. Однако из дворца Топкапы настоятельно требовали достать Нусрет-пашу даже из-под земли. Тогда некто с жиденькой бородкой и больными красными глазами посоветовал главному визирю обратиться за помощью к Коста-бею, греку, о котором было известно, что он колдун и общается с самим шайтаном. Когда к нему обратились, Коста-бей прищурил левый глаз, цокнул языком и согласился. За плату в двадцать золотых динаров он взялся за это дело, попросил только не беспокоить его, пока он сам не даст знать, что паша убит. Коста-бей заперся на втором этаже своего дома в Фанаре, разложил карты, опять поцокал языком и написал письмо, где подробно описал кого, когда и где нужно найти и убить. Он вложил в это письмо часть денег, полученных авансом, и тот самый шёлковый шнурок, которым собирались убить пашу, и отправил в Тебриз. Письмо было без адреса, вернее на нём были всего одна османская и одна персидская печать. Шайтан, которому Коста-бей его отправил, сам нашёл это письмо на перекрёстке перед въездом в город в безлунную ночь. Монеты, спрятанные в письме, он пересчитал, остался доволен, часть отсыпал себе в карман, а остальную часть проглотил, шнурок же завязал на своем левом запястье. От того шайтана пахло гвоздикой, лимонной цедрой и розовой водой, как от рожавшей женщины."},{"kind":"paragraph","text":"Пока Нусрет-пашу искали, он, уже окончательно ставший Хасаном, научился бегло говорить на фарси, нагло обманывать"},{"kind":"paragraph","text":"и жалобно скулить. Он устроился поваром в том самом караван-сарае, где потратил последние деньги. Теперь рядом с ним всегда стояли запахи вареного риса, варёной баранины и варёных бобов. Когда он готовил горме сабзи или аше решт, то закатывал глаза, и на его лице играла наивная улыбка. Он мягко резал мясо, солил его и перчил, так, что ни один кристаллик соли не просыпался на пол. Он умело и очень мелко нарезал зелень кинзы и баклажаны, так чисто мыл рис, что каждое зёрнышко сверкало в его руках. «Раньше я мог одним ударом своего меча разрубить врага пополам, а сейчас мои руки так искусно готовят еду, как будто я всю жизнь это делал», — думал бывший паша и распространял вокруг себя запахи базилика, мяты и петрушки. Однако, так как без усов бывший паша был похож на шакала, когда он улыбался, его лицо было столь безобразным, что люди в ужасе отворачивались от него, чтобы не видеть эту улыбку."},{"kind":"paragraph","text":"Однажды во сне он увидел, что на нём скачет женщина с большой, белой как молоко грудью. Она закатывала глаза и громко стонала. От этой женщины пахло гвоздикой, розовой водой и ещё чем-то кислым, что сбивало все ароматы, но Нусретпаша никак не мог определить, что это за запах. Паша понял, что спит и видит сон, он понимал, что проснётся с мокрыми штанами, и утром ему придётся совершать полное омовение — гусл. Но он очень не хотел просыпаться. И вот скачущая на Нусрет-бее женщина вдруг приподняла его голову и обвила вокруг его шеи змею. Он испугался и хотел было проснуться, но у него не получилось. Тогда змея облизнула своим языком его губы и прошептала: «Между Солнцем и Луной проходит тонкая граница в полсекунды полёта, это границу можно пересечь, но только в одном направлении. От Солнца к Луне, но никак иначе. Нужно было бежать на Запад, Нусрет-паша». После этих слов повар Хасан проснулся с мокрыми штанами и медленно побрёл в умывальную комнату совершить гусл и сменить штаны."},{"kind":"paragraph","text":"В то же время шайтан, которому поручили найти и убить беглого пашу, продолжал жить своей обычной жизнью торговца письменными принадлежностями и особо не торопился исполнять поручение. Каждое утро он открывал свою лавку в Тебризском базаре, обслуживал покупателей, пересчитывал товар и всё время улыбался. Однажды вечером к нему забрёл странствующий дервиш, от которого шёл запах сандалового дерева."},{"kind":"paragraph","text":"— Салам Алейкум, хозяин."},{"kind":"paragraph","text":"— Ва-Алейкум-ас-салам."},{"kind":"paragraph","text":"— Я хочу купить у тебя тетрадь и несколько каламов, чтобы записывать то, что вижу и слышу."},{"kind":"paragraph","text":"— Выбирай любые. Для тебя я снижу цену наполовину, святой человек."},{"kind":"paragraph","text":"— О нет, не называй меня святой человек, я обычный грешник, как и все, — возразил дервиш. У него была белая как молоко кожа, такого же цвета волосы и седая борода. Когда на дервиша падал свет, то отражался от его кожи, как от зеркала, и казалось, что не отведя взгляд, можно ослепнуть."},{"kind":"paragraph","text":"— Почему же ты грешник? Ты всё время молишься, соблюдаешь пост, читаешь Священный Коран. Даже если у тебя есть грехи, то не такие большие, как у многих."},{"kind":"paragraph","text":"— Ты прав, я стараюсь соблюдать все заповеди нашей религии, но даже при этом я не могу быть уверенным, что всё делаю правильно."},{"kind":"paragraph","text":"— Я тебя не понимаю! — удивился шайтан."},{"kind":"paragraph","text":"— Хочешь расскажу одну курдскую легенду, которую я услышал в Диярбакыре?"},{"kind":"paragraph","text":"— Расскажи."},{"kind":"paragraph","text":"— Однажды пророк Моисей, Муса-пейгамбар, шёл по своим делам и увидел, как один старик взбирается на холм, а потом кубарем скатывается с него. Муса-пейгамбар очень удивился"},{"kind":"paragraph","text":"и стал смотреть, что этот старик делает. Тот снова полез на холм, и опять кубарем скатился с него. Тогда пророк подошёл к нему и спросил: «Мир тебе, отец! А что ты делаешь? Почему ты поднимаешься на холм и скатываешься с него?». Старик ответил ему: «И тебе мир, Муса-пейгамбар! Я так молюсь Богу!». Пророк ещё больше удивился и сказал: «Разве так можно молиться? Давай, я научу тебя, как это правильно делать». Старик согласился и Муса-пейгамбар научил его правильно молиться, мыть руки и лицо, становиться прямо, делать поклоны, поворачивать лицо как положено, научил его словам молитвы и после этого они вместе помолились Аллаху и Муса-пейгамбар продолжил свой путь, оставив старика одного. Он подошёл к морю, ударил своим посохом, море расступилось перед ним, и пророк пошёл дальше. Но когда он был на середине моря, он услышал, что его кто-то зовёт. Повернувшись, Муса-пейгамбар увидел, как за ним бежит тот самый старик. «Что случилось, отец?» — спросил он. «Я забыл слова молитвы, Муса-пейгамбар! Что надо говорить, когда делаешь земной поклон?» — закричал старик. Муса-пейгамбар посмотрел на него и увидел, что ноги старика сухие, хотя он бежал по мокрому морскому дну, а ноги самого Мусы-пейгмабара мокрые. «Не надо никаких слов, отец! Твоя молитва ближе Аллаху, чем моя. Иди и молись как раньше», — сказал Муса-пейгамбар и пошёл дальше по своим делам. Вот такая история, — закончил свой рассказ дервиш."},{"kind":"paragraph","text":"— Ничего не понял, — сказал хозяин лавки. — Я, наверное, слишком необразован, чтобы понимать такие притчи. Извини меня."},{"kind":"paragraph","text":"— Это ты меня извини, добрый человек, — ответил дервиш. — Я отвлекаю тебя своими притчами, а ведь зашёл всего лишь за тетрадью и каламом. Продай мне, пожалуйста, вон ту книжку и обычный калам, — попросил дервиш и указал на маленькую чёрную книжку в самом углу лавки."},{"kind":"paragraph","text":"— Прости меня, святой человек, не могу её продать, это моя книжка. Я в ней записываю свои дела и веду счета. Лучше продам тебе вот эту, за полцены, — и показал на лучшую тетрадь в его лавке с позолоченным тиснением. Её мне привезли из Исфахана. Чистая тетрадь в сто листов. Бумага китайская, а калам я тебе советую взять местный, тебризский. Они самые лучшие и почти не портятся."},{"kind":"paragraph","text":"— Ты такой добрый, — улыбнулся дервиш. Он оплатил нужную сумму и вышел из лавки."},{"kind":"paragraph","text":"Как только он вышел, шайтана пробили пот и трясучка. В тот день ему стало плохо, и он закрыл лавку ещё до захода солнца. Весь следующий день его била лихорадка, и он истекал вонючим потом. От него смердело луком, чесноком и недоваренным говяжьим хвостом. «Больше никогда не пущу ангелов ко мне в лавку!» — думал он, вытирая со лба пот."},{"kind":"paragraph","text":"Пока шайтан лежал в лихорадке и потел, Нусрет-паша изнывал от другой напасти. Каждую ночь ему снилась та самая женщина, которая оседлала его, и каждый раз ему приходилось после неё совершать полное омовение. «Так больше нельзя! Я с ума сойду от воздержания! Надо на кого-то залезть» — думал паша и ещё больше распалял свое воображение. Он потерял покой и погрузился в свои мысли и сны. Его блюда теперь больше пахли тмином, зирой и чесноком. В них появилось много соли и масла. Рис его плова просто плавал в жире, и постояльцы Караван-сарая очень удивлялись, тому, как привычные блюда меняют вкус, цвет и аромат. Однажды хозяин попросил его приготовить бадемджан, по вкусу одного постоянного гостя, ахунда мечети из Шираза. Нужно было просто обжарить баклажаны с луком и чесноком, как любил гость. Бывший Нусрет-паша так был поглощён своими мыслями, что вместо обычного бадемджан приготовил свой любимый османский имам баялды. Ахунд"},{"kind":"paragraph","text":"был в восторге и чуть не упал в обморок от удовольствия. Он подарил хозяину Караван-сарая молитвенный коврик из дорогой ткани и послал повару серебряный аббаси за такое вкусное блюдо. А хозяин, когда узнал сколько оливкового масла из его запасов истратил новый повар, тоже чуть не упал в обморок. Так в руках беглого паши имам баялды сменил веру и превратился в ахунд баялды."},{"kind":"paragraph","text":"После выздоровления шайтан вновь открыл свою лавку, но неделю торговал только до аср-намаза, после чего закрывался изнутри и готовился к важному делу. Он купил отрез шёлковой материи и сшил из него себе красивое женское платье. После этого он купил сурьму, хну и египетскую помаду. Теперь от него пахло розовой водой, жасмином и бардакушем. Он вычистил свою кожу, так, что она стала белой как молоко и без единого волоска. Натер себя маслами и благовониями, обвязался тонкой тканью и пролежал так всю ночь, пока его тело не стало мягким и нежным, как тело женщины. Он сел перед зеркалом и начал рисовать себе новое лицо. Это было лицо персидской женщины, которую он увидел очень давно. Может быть, та женщина уже умерла, а может быть, превратилась в немощную старуху. Шайтан нарисовал себе красивые округлые брови, но не стал их соединять, показывая тем самым, что это лицо замужней женщины. Он подвёл сурьмой глаза и накрасил египетской помадой губы. У него было прекрасное женское лицо, но в нём было что-то едва уловимое, отталкивающее, что-то омерзительное. Если внимательно приглядеться, то можно было видеть, что его левый глаз похож на букву «мим», а правый на букву «уау» и хвостики обеих букв образуют тонкую линию носа. Его накрашенные губы были похожи на лодочку, а ноздри на две точки, как будто это была буква «та». На лице женщины-шайтана было написано по-арабски «маут» — что значит «смерть»."},{"kind":"paragraph","text":"В один зимний четверг, который был таким холодным, что стыла только что приготовленная еда, Нусрет-паша отправился на базар за покупками. Он обошёл лавки мясника, зеленщика, продавца овощей и продавца сладостей, купил рис, масло, лук и чеснок. Но пока он ходил по торговым рядам и делал покупки, он не почувствовал никакого запаха. Ни мясо, ни овощи, ни куркума, ни зира, даже сладкая бамия и джелеби ничем не пахли. Как будто нос беглого паши закрылся от всего мира, хотя он не болел и не был заложен. Нусрет-бей совсем не обращал на это внимания, его голова была занята мыслями о женщинах. Он изнывал от желания, так что каждое утро совершал большое омовение. Другие служители караван-сарая посмеивались над ним. От их насмешек и ёрничанья безобидный повар убегал на базар. Пока он бродил по огромному рынку, за ним следовали два женских глаза, похожие на буквы «мим» и «уау»."},{"kind":"paragraph","text":"Нусрет-бей стоял у двери в маленький неприметный магазинчик письменных принадлежностей. Он был настолько поглощён своими мыслями, что ничего не замечал вокруг. Его слегка толкнула проходившая мимо женщина, Нусрет-паша обернулся, чтобы посмотреть, кто его толкнул, и его прошиб холодный пот — как во сне. Через прорезь в чадре на него смотрели те самые глаза, которые он видел каждую ночь. В эту минуту умерла последняя капля его мужества, бывший паша окончательно стал трусом и понял, что погиб. Он до смерти испугался женщину, о которой мечтал, как мальчишка. Нусрет-бей заметил, что глаза смотрят на него с улыбкой. Чтобы спрятаться от этого страшного и влекущего взгляда, он вбежал в лавку для писцов и каллиграфов. В ней было пусто, как в доме, из которого ушли хозяева. Сюда не доносился шум многолюдного базара, и внутри лавки было тепло и уютно. Не было ни владельца, ни продавца, ни покупателей — никого. Только на прилавке лежала открытая на середине тетрадь в чёрном переплёте, как буд-"},{"kind":"paragraph","text":"то её кто-то читал до прихода Нусрет-бея, но второпях оставил недочитанной и убежал. На самом деле тетрадь была недописанной, в ней не хватало пары абзацев о том, как некий персидский шайтан убил турецкого пашу, сбежавшего от гнева султана в Иран. Случайно заглянув в тетрадь, бывший паша прочел фразу, которая показалась ему знакомой, но он никак не мог вспомнить, где её слышал. «Между Солнцем и Луной проходит тонкая граница в полсекунды полёта, это границу можно пересечь, но только в одном направлении. От Солнца к Луне, но никак иначе. Нужно было бежать на Запад». Нусрет-паша оглянулся, нет ли поблизости кого-нибудь, и быстро схватив тетрадь, спрятал её во внутреннем кармане халата. Он быстро вышел из лавки и на него сразу же накинулись сотни запахов. Это были запахи всех специй и фруктов, запахи овощей и мяса, сладостей и чая, даже запахи женщин и мужчин, запахи стариков и детей, ковров, украшений, меди и бронзы, кухонной утвари и деревянной мебели, запахи шёлковых одежд и подушек, набитых шерстью. У бывшего паши закружилась голова, он схватил сумки с покупками и смешно засеменил к выходу. Он быстро шёл и ловко уворачивался от людей, шедших ему навстречу, чтобы ни с кем не столкнуться. Словно маленький ветер, паша вылетел из базара и через пару минут уже заходил в ставший ему родным караван-сарай."},{"kind":"paragraph","text":"В тот вечер он приготовил особенный ужин для хозяина и постояльцев караван-сарая. Он нарезал баранину тонкими кусочками, замариновал её перцем, луком, солью и душистыми травами. Вымыл рис в такой холодной воде, что его руки посинели, но бывший паша этого даже не заметил. Он залил казан на одну десятую сливочным маслом и с помощью тонкого лаваша протер маслом его стенки. Словно ковром, он устлал дно и стенки казана лавашом. Потом он сложил на дно казана слоями перец, лук, кусочки айвы, кусочки баранины, залил"},{"kind":"paragraph","text":"всё это кипятком, так, что верхушка оставалась не затопленной и поставил томиться на медленный огонь. Когда вода закипела, Нусрет-бей кинул в казан сушёного чернослива для кислинки и тушил баранину с овощами, пока слёзы не показались на его глазах. Потом он посыпал баранину щепоткой сумаха, так, что его можно было увидеть, но вкус, чтобы насладиться им, ещё нужно было уловить. Отдельно он сварил в чистой, как слезы, родниковой воде рис и дал ему немного остыть. После этого он равномерно разложил рис на большом блюде и сверху положил баранину с луком и черносливом. Всё это он полил горячим маслом и подал на стол. Сидевшие за столом гости молча, не проронив ни слова, смотрели на похожего на шакала повара и еле сдерживали текущие слюнки от запаха приготовленного им плова. Такого роскошного ужина в бедном караван-сарае не было ни до, ни после Нусрет-паши. Это был плов достойный шаха Аббаса."},{"kind":"paragraph","text":"Никто не сказал ему спасибо — во время ужина было слышно только чавканье и сопение сытых, но продолжающих есть гостей. После ночного намаза, когда все пошли спать, к повару подбежал мальчишка-слуга и сказал, что его спрашивает какая-то женщина. Когда бывший паша подошёл к воротам караван-сарая, его сердце бешено стучало в груди, ноги подкашивались, и запах страха крепко обнял его. Его ждала та самая женщина из его снов, которую он сегодня видел на базаре."},{"kind":"paragraph","text":"— Сегодня, ты случайно, сам того не сознавая, забрал у меня что-то очень важное, — сказала она и пристально посмотрела ему в глаза. — Вот я и пришла за своей тетрадью. Отведи меня к себе."},{"kind":"paragraph","text":"У Нусрет-паши язык прилип к горлу, он молча повернулся и повёл женщину в свою каморку. Их никто не видел, даже тот"},{"kind":"paragraph","text":"мальчишка на следующий день совершенно забыл о том, что повара спрашивала какая-то женщина."},{"kind":"paragraph","text":"В его келье она сняла с себя чадру и впилась большими как у гурии глазами в бывшего пашу."},{"kind":"paragraph","text":"— Не бойся меня. Ведь ты всё время видел меня в своих снах. Вот я и пришла к тебе."},{"kind":"paragraph","text":"Она стала раздевать Нусрет-бея и заставила его лечь. Его страх сменился страстью, он уже не понимал, что делает. Паша потянулся рукой, чтобы прикоснуться к ней между ног, но женщина одернула его руку."},{"kind":"paragraph","text":"— Не трогай меня там, я сама всё сделаю, — и залезла на него, точно так же, как и в его снах. Её грудь была белой, не такой, как у персидских или османских женщин, тело было мягким, как тело девочки. Она, закатив глаза скакала на нём, распространяя вокруг себя запах гвоздики, розовой воды и ещё чего-то кислого. Она не сняла полностью одежду, поэтому Нусрет-паша не видел её лона, она прикрыла его живот своей чадрой. Пока она скакала на нём, что-то мягко ударялось о живот паши, когда же он случайно приподнял её чадру, то увидел мужской член. Паша даже не успел крикнуть, как вокруг его шеи завязался шёлковый шнурок. Теперь он понял, что этот непонятный, кислый запах был запахом мочи."},{"kind":"paragraph","text":"— Между Солнцем и Луной проходит тонкая граница в полсекунды полёта, это границу можно пересечь, но только в одном направлении. От Солнца к Луне, но никак иначе. Нужно было бежать на Запад, Нусрет-паша. От османского полумесяца нужно было бежать не в Иран, не к Солнцу, а хотя бы в сторону Дубровника или Шкодера. А там и до Венеции"},{"kind":"paragraph","text":"недалеко. Ты выбрал неправильный маршрут, Нусретпаша. А убить тебя приказали за то, что ты казнокрад и не поделился с Великим визирем, — сказал шайтан и лизнул лицо задыхающегося паши длинным змеиным языком."},{"kind":"paragraph","text":"На следующий день хозяин караван-сарая пошёл будить повара и нашёл того мертвым и залитым своим же семенем так обильно, как будто он всю ночь сношался с целым гаремом. На его шее был след от шнурка, но самого шнурка не нашли. А через неделю Коста-бей в Фанаре получил письмо из Тебриза со шнурком и сдачу в несколько акче — за то, что работа принесла шайтану не только деньги, но и удовольствие."}]'::jsonb, '2020-12-30T12:00:00.000Z'
) ON CONFLICT (slug) DO UPDATE SET
  title=EXCLUDED.title, author_id=EXCLUDED.author_id, cover_path=EXCLUDED.cover_path,
  cover_blur=EXCLUDED.cover_blur, cover_width=EXCLUDED.cover_width, cover_height=EXCLUDED.cover_height,
  excerpt=EXCLUDED.excerpt, content_blocks=EXCLUDED.content_blocks, published_at=EXCLUDED.published_at;

INSERT INTO "Articles" (slug, title, author_id, cover_path, cover_blur, cover_width, cover_height, excerpt, content_blocks, published_at)
VALUES (
  'mrd1-domashnee-chtenie', 'Домашнее Чтение',
  (SELECT id FROM "Authors" WHERE name = 'Арчет' ORDER BY id LIMIT 1),
  'mrd1/mrd1-domashnee-chtenie.jpg', 'data:image/jpeg;base64,', 947, 583,
  'А. Алая буква', '[{"kind":"image","path":"mrd1/mrd1-domashnee-chtenie.jpg","caption":null},{"kind":"paragraph","text":"А. Алая буква"},{"kind":"paragraph","text":"Наверное, вы не читали эту книгу. А если читали, мой вам привет. В ней рассказывается о том, как женщину все презирали за адюльтер. Но она знала, что вела себя правильно, потому что любила этого человека. У меня всё было наоборот. До шестнадцати лет меня насиловал отчим, и все вокруг считали, что лучше этого не замечать."},{"kind":"paragraph","text":"Б. Букварь"},{"kind":"paragraph","text":"Я росла без компьютера и считала это нормальным. Связи с окружающим миром не было вообще. Сейчас я понимаю, что вышло так не случайно. Сергей Валентинович (так зовут моего отчима) специально ограничил контакты с людьми, чтобы я жила в мире, все правила которого придумывал он."},{"kind":"paragraph","text":"Например, я была уверена, что учусь дома, потому что меня стыдно отпускать к другим детям — настолько я глупая и без-"},{"kind":"paragraph","text":"дарная. На самом деле после четвёртого класса я сдавала школьную программу экстерном."},{"kind":"paragraph","text":"Я могла бы до сих пор жить в выдуманном мире. Сергей Валентинович очень умный. И хитрый. Он сделал только одну ошибку. Не отнял у меня букварь вовремя."},{"kind":"paragraph","text":"В. Властелин колец"},{"kind":"paragraph","text":"Конечно же, у меня не было ни телефона, ни планшета, ничего в этом роде. И я не знала, что вокруг «Властелина» огромное количество людей, которые буквально живут в Средиземье."},{"kind":"paragraph","text":"Но это не мешало мне стремиться туда. Одна из немногих вещей, которые я помню о матери — запах, почему-то персиковый, большие ласковые ладони и голос. Ну... мамин голос. Она читала мне «Властелина колец» вслух. И когда я немного выросла, я тоже захотела прочесть Толкиена. Это всё, что у меня осталось от мамы. Я не помню её лица."},{"kind":"paragraph","text":"Г. Герой нашего времени"},{"kind":"paragraph","text":"Главный герой показался мне очень похожим на отчима, каким он должен был быть лет десять назад. Поэтому я так и не смогла ощутить к нему сопереживание. Не поймите неправильно, на тот момент я считала Сергея Валентиновича богом. Даже не так — Богом. Жестоким, не очень умным, и только ему было ведомо, как ПРАВИЛЬНО жить. Сопереживать ему я не могла. Но..."},{"kind":"paragraph","text":"Ветхий Завет велит убивать камнями за одежду из разных тканей. А если голоса в голове сказали тебе порешить сына Исаака, значит судьба такая. Так что Иисусу я сопереживала всегда. Ему не повезло с папой."},{"kind":"paragraph","text":"Вы, наверное, не понимаете, что происходит? В комнате, где я суммарно провела взаперти пятнадцать лет из шестнадцати, был книжный шкаф. Огромный, вместе с книгами он весил, наверное, тонну. Его было невозможно не то что сдвинуть, а даже поколебать. Глыба."},{"kind":"paragraph","text":"А это мой читательский дневник, как я его себе представляю. Всё детство книги были моей единственной связью с миром вне комнаты."},{"kind":"paragraph","text":"Д. Джек Лондон"},{"kind":"paragraph","text":"Иногда я думаю вот о чём — ведь это были его книги, отчима. Ну или его отца, моего дедушки. Так или иначе, ктото из них с удовольствием читал Джека Лондона. Как можно переживать за персонажа, который совершенно на тебя не похож? Читать о том, как смелые и добрые люди покоряют Северный полюс, а потом бить жену?"},{"kind":"paragraph","text":"Или персонажи Лондона тоже плохие? Или мой отчим на самом деле хороший? Ну, это точно нет. Но разве можно сопереживать герою книги неискренне? Кому тут врать, — Лондону?"},{"kind":"paragraph","text":"Е. Если"},{"kind":"paragraph","text":"В основании шкафа лежало много журналов, больше художественных. От какой-то советской «Крестьянки» и «Звезды» до «Литературной газеты». Но мне больше всего запомнился журнал «Если». Это были фантастические рассказы, и я помню, как не понимала многие из них. Почему? Потому что они рассчитаны на людей, которые живут в обыкновенном мире и сравнивают всё с ним. А я жила в мире, который выдумал Сергей Валентинович."},{"kind":"paragraph","text":"Его любимой фразой было «Я — последняя буква алфавита». Со временем я выработала язык, в котором не было высказываний от первого лица. Наверное, психологам и лингвистам это бы очень понравилось."},{"kind":"paragraph","text":"Ё. Ёмкостные преобразователи"},{"kind":"paragraph","text":"В моей комнате, а значит, и в нашем доме не было технической литературы. Не знаю, как приблудились эти «Преобразователи», но это была одна из первых книг, которую я попробовала прочесть. Потому что она была тонкая и там было много картинок. Совершенно мне непонятных, конечно. Но всё равно я была поражена. Где-то есть люди, которые занимаются вот этим. Наверное, они совсем не такие, как я. Я — пустое место. Ненужная ёмкость, которую не преобразовать."},{"kind":"paragraph","text":"Ж. Жюль Верн, собрание сочинений"},{"kind":"paragraph","text":"Как ни странно, эти книги (красивые тома с золотыми буквами на обрезе) напрямую ассоциируются у меня с «Преобразователями». Помню, меня очень впечатлил Сайрус Смит из «Таинственного острова», который разводил огонь с помощью стекол от пары часов. Я ничего не знала о науке, но чувствовала, как у него много общего с теми людьми, которые веком позже написали тонкую книжку про электронику, непонятно кому и зачем нужную. Зачем было нужно то, что делали герои Жюля Верна, я понимала прекрасно. В основном они выживали. Совсем как я."},{"kind":"paragraph","text":"З. Заводной апельсин"},{"kind":"paragraph","text":"А этот мир был очень похож на мой. Настолько, что фразу «Старое доброе ультранасилие» я считала не как иронию, а как факт. Только мораль была странная. Победили не «хорошие», а «плохие»."},{"kind":"paragraph","text":"И. Идиот"},{"kind":"paragraph","text":"Не дочитала. Хотя мне очень понравился Мышкин, но... как обречённый на смерть щенок, играющий в яме, которую заливают бетоном. Всё его детское мироощущение мимо. Я никогда не была ребёнком."},{"kind":"paragraph","text":"К. Крёстный отец"},{"kind":"paragraph","text":"Тут мне тоже почти всё было понятно, кроме главного: откуда у них такие тёплые отношения в семье. Особенно к приёмным детям. С каких пор это стало так важно? И второе. В начале книги Дон Корлеоне говорит что-то в духе: «Весь ваш закон — фигня. Как только доходит до настоящего дела, вы не надеетесь на него, вы идёте ко мне». А в конце извиняется перед сыном: «Я думал, тебе не обязательно будет вести дела, как я. Я думал, ты станешь сенатором Корлеоне...»"},{"kind":"paragraph","text":"Зато кем стал его сын, мне очень понравилось. Тогда. Хотя и закрались сомнения."},{"kind":"paragraph","text":"Л. Лолита"},{"kind":"paragraph","text":"Много разного можно сказать об этой книге, но за что я могу сказать спасибо Набокову — я поняла, что в моём положении реально манипулировать. Не то чтобы я горжусь этим. Дело в том, что отношения Гумберта и Ло на тот момент казались мне вполне здоровыми и органичными. Гумберт Гумберт — это была моя версия «принца на белом коне»."},{"kind":"paragraph","text":"М. Маленький принц"},{"kind":"paragraph","text":"Согласна, с Лолитой сочетается странно, но я прочла его очень поздно и почти параллельно с ней. Возможно, именно эта книга меня и переломила. В нужную сторону. Она написана языком, которым нельзя врать. И то, что в ней написано, не буду ездить вам цитатами по ушам, было совсем непохоже на то, что я слышала от отчима каждый день."},{"kind":"paragraph","text":"В том, что может соврать Сергей Валентинович, сомнений не было никаких. Он много раз делал это при мне. Например, постоянно врал моей учительнице по поводу синяков и шрамов."},{"kind":"paragraph","text":"Н. Над пропастью во ржи"},{"kind":"paragraph","text":"Учительница ходила к нам почти каждый день. Не знаю, почему отчим решил дать мне какое-то образование. Наверное, подумал, что так я буду ему полезнее. На самом деле учительница была не одна, но Юлия Алексеевна запомнилась сильнее всего. Она учила меня почти всем предметам, когда я стала постарше."},{"kind":"paragraph","text":"И потому что стала частью моего плана."},{"kind":"paragraph","text":"Сэлинджер на фоне безвыходного экстерна показался мне куда фантастичнее Жюля Верна. Мальчик сам куда-то едет, чтото решает, высказывает мнение. И все воспринимают это нормально. Такого в реальности не бывает. Но знаете, что я думаю сейчас?"},{"kind":"paragraph","text":"Да, я не поверила. Но тексты влияют на нас очень сильно, хотим мы этого или нет. Даже если мы не согласны, просто попадая в сознание раз за разом, они меняют нас и делают похожими на себя."},{"kind":"paragraph","text":"Наверное. Я не знаю. Мой отчим читал те же книги, на которых выросла я. Может быть, это работает не всегда? Или можно предать книги?"},{"kind":"paragraph","text":"Однажды я попыталась обсудить прочитанное с Сергеем Валентиновичем, чтобы понять это, но он избил меня и отнял «Над пропастью»."},{"kind":"paragraph","text":"О. Одиссея"},{"kind":"paragraph","text":"Метафора, которая запала мне в душу — Сцилла и Харибда, как, наверно, и всем. Я чуть не запищала от восторга, когда нашла её, настолько это было похоже на две личности Сергея Валентиновича, между которыми я лавировала, как корабль, одновременно стараясь, чтобы меня не съели и не утянули с собой на дно."},{"kind":"paragraph","text":"Это было очень непросто. Как я потом узнала, «расщепление личности» не только поэтично звучит, но и очень точно описывает моего отчима. Способность одновременно быть ласковым и жестоким, с переходом от одного к другому за считанные секунды. А ещё он был очень хитрым."},{"kind":"paragraph","text":"Я могла бы рассказать об издевательствах очень много подробностей, но я уже столько рассказывала о них, что больше не хочется. Представьте, что у вас во рту шоколадка. Вы сжимаете челюсти, а внутри у конфеты обломок бритвы. Вот так это ощущается. И вы уверены, что ВСЕ конфеты такие."},{"kind":"paragraph","text":"П. Происхождение видов"},{"kind":"paragraph","text":"Ключевая мысль Дарвина мне очень понравилась. Она ведь не про то, что выживает сильнейший. Выживает наиболее приспособленный. Это полностью отвечало моему опыту."},{"kind":"paragraph","text":"Довольно поздно я поняла, что жить по-человечески и выживать — очень разные вещи. Иногда друг с другом не совместимые."},{"kind":"paragraph","text":"Р. Робинзон Крузо"},{"kind":"paragraph","text":"Вот, например, Робинзон. Он, конечно, выживает. Но ведь он легко мог выживать и дальше, а выбрал жить. Я поняла, что тоже хочу Жить."},{"kind":"paragraph","text":"С. Собачье сердце"},{"kind":"paragraph","text":"Быть может, вам кажется, что в этой книге всё очевидно. Легко осудить Шарикова и посмеяться над ним. Но я должна сказать, он сделал большие успехи."},{"kind":"paragraph","text":"Многим кажется, что НЕ быть Шариковым просто. Наверное. Для вас. Понимаете... вы никогда не были псом. А это здорово влияет на восприятие."},{"kind":"paragraph","text":"Мне его жалко. Говорят, что собаки не думают о себе от первого лица."},{"kind":"paragraph","text":"Т. Трудно быть богом"},{"kind":"paragraph","text":"Я прочитала довольно много фантастики, но эта, наверное, единственная, где мне хотелось бы жить. Не в Арканаре, конечно, а на той Земле будущего, откуда прилетел к ним Румата. Возможно, её никогда не будет. Но именно прочтя эту книгу, я поняла, что стремление — тоже важно. Стремиться к тому, чего не видишь и не увидишь — в этом есть что-то от Экзюпери, и даже от науки с её абстрактными принципами."},{"kind":"paragraph","text":"Но бывают ли не абстрактные принципы?"},{"kind":"paragraph","text":"У. Убить пересмешника"},{"kind":"paragraph","text":"Наверно, бывают. Например, когда Аттикус пошёл защищать негра от линчевания, вряд ли он раздумывал над отвлечёнными моральными установками. Он просто пошёл, потому что так было правильно."},{"kind":"paragraph","text":"Все «правильно» задаются нам в детстве, но именно прочитав эту книгу, я поняла, что есть и ещё какое-то «правильно». Не божественное, нет, а вполне человеческое. Я вообразила себе, что человечество — это одна личность. Уже мёртвые люди — его прошлое, нерождённые — будущее. А я —"},{"kind":"paragraph","text":"настоящее. Маленький синапс в семимиллиардном мозге. Да, я совсем маленькая. Но я тоже решаю, что правильно, а что нет."},{"kind":"paragraph","text":"У кого-то другое «правильно», а у меня такое — родившееся из мыслей, записанных на бумаге. Это не абсолютная истина. Но это правда."},{"kind":"paragraph","text":"Ф. Фауст"},{"kind":"paragraph","text":"Не самая свежая мыль, но скорость тьмы больше скорости света. Не уверена, правильно ли это с точки зрения физики, но свету нужно время, чтобы куда-то попасть. А когда свет исчезает, тьма заменяет его мгновенно. Всегда ли прав тот, кто быстрее, сильнее, наиболее приспособлен? Нет."},{"kind":"paragraph","text":"Не существует того, кто прав. Даже Бог убивает невинных, если он есть, и устраивает таким, как я, ад ни за что."},{"kind":"paragraph","text":"Существуют лишь те, кто не сомневается в истине, и те, кто стремится к ней постоянно, без надежды прийти к финишу."},{"kind":"paragraph","text":"Мы не встанем на почётные пьедесталы с первого до третьего места. В этой лестнице больше трёх ступеней, — и у неё нет конца в небе."},{"kind":"paragraph","text":"Поэтому я решила украсть телефон."},{"kind":"paragraph","text":"Х. ХХ век: Новейшая история"},{"kind":"paragraph","text":"Её принесла Юлия Алексеевна, и я глубоко впечатлилась невыдуманной историей. Придумать можно всё что угодно. Но это было. Она не смогла преподать мне историю так, чтобы у меня не появилось вопросов к миру вокруг. Возможно, это была главная ошибка моего отчима после букваря."},{"kind":"paragraph","text":"История была по средам, и каждое занятие во мне крепла уверенность, что пора что-то делать. Похоже это было заметно со стороны. Отчим почувствовал неладное и запретил подходить к книжному шкафу."},{"kind":"paragraph","text":"Ц. Цветы для Элджернона"},{"kind":"paragraph","text":"Несколько книг я всё-таки ещё успела прочесть тайно. Например, «Цветы». Помните эпизод, где бедный глупый уборщик не понимает, что над ним издеваются сослуживцы — ему кажется, что они его любят, и всё такое? А потом он умнеет."},{"kind":"paragraph","text":"Вот и я поумнела."},{"kind":"paragraph","text":"Ш. Шерлокиана"},{"kind":"paragraph","text":"Шерлок Холмс научил меня делать выводы и планировать. Когда они с Ватсоном сами пошли на преступление, то напортачили, где только могли. Я постаралась избежать их ошибок. Пошла к отчиму и стала обсуждать с ним всё, что прочитала за свою жизнь."},{"kind":"paragraph","text":"Щ. Щелкунчик"},{"kind":"paragraph","text":"Да, это было сродни самоубийству, можете не рассказывать. Почти неделю я с трудом ходила до туалета, — так он меня избил. Но главного я добилась. Через пару дней отчим принёс в мою комнату несколько огромных коробок, сложил туда все книги и вынес их на помойку. Осталось только детское издание «Щелкунчика» под ножкой шкафа."},{"kind":"paragraph","text":"Ъ. Газета, кажется, Коммерсант"},{"kind":"paragraph","text":"Ещё остались газеты, несколько штук. Они были за шкафом, и я нашла их, когда впервые сдвинула эту махину с места. Всё тело болело, но мне удалось. Конечно, я не могла сдвинуть шкаф вместе с книгами, а если бы я начала вынимать их, это навело бы Сергея Валентиновича на мысли. Поэтому пришлось идти ва-банк."},{"kind":"paragraph","text":"Ы. Это просто моя любимая буква"},{"kind":"paragraph","text":"Возможно, потому что кто-то вырезал эту букву на книжном шкафу. Мне нравится думать, что мама. И я смотрела на неё перед сном всю жизнь. А теперь не смотрю. У меня была не алая буква, а тёмно-коричневая."},{"kind":"paragraph","text":"Ь. Туалетная бумага"},{"kind":"paragraph","text":"Сергей Валентинович почему-то любил именно такую. Мягкий знак."},{"kind":"paragraph","text":"Когда я выздоровела, Юлия Алексеевна вернулась, чтобы меня учить. И у неё был сотовый телефон, пароль от которого я подсмотрела заранее и зазубрила."},{"kind":"paragraph","text":"Во время урока я специально перекосила челюсть. Из ран на внутренней поверхности щёк, которые не зажили за неделю, пошла кровь. Я сплюнула ей на учебник. Юлия Алексеевна хотела сразу же отвести меня в ванную, но я её успокоила, как обычно в таких случаях, попросила сбегать в туалет и принести оттуда бумаги. Она пошла."},{"kind":"paragraph","text":"Телефон остался."},{"kind":"paragraph","text":"Э. Эсквайр"},{"kind":"paragraph","text":"Это хороший журнал. А особенно он хорош тем, что даже в старых выпусках там были материалы о домашнем насилии. С номерами телефонов."},{"kind":"paragraph","text":"Когда учительница ушла, я задвинула дверь шкафом и совершила звонок."},{"kind":"paragraph","text":"Так себе кульминация? Поверьте, не для меня."},{"kind":"paragraph","text":"Ю. Ювенальная юстиция"},{"kind":"paragraph","text":"Книга, которую не читал Сергей Валентинович. А я теперь знаю её хорошо."},{"kind":"paragraph","text":"не очень жалею о книгах. Мне не кажется, что я предала их. Наоборот. Я сделала так, как было написано."},{"kind":"paragraph","text":"Чуть позже, проезжая мимо нашего дома, я увидела, что огромные коробки стоят на помойке, под жестяной крышей, и почти все книги оттуда разобраны."},{"kind":"paragraph","text":"Я собрала оставшиеся и отнесла их в библиотеку."},{"kind":"paragraph","text":"Спасибо."}]'::jsonb, '2020-12-30T12:00:00.000Z'
) ON CONFLICT (slug) DO UPDATE SET
  title=EXCLUDED.title, author_id=EXCLUDED.author_id, cover_path=EXCLUDED.cover_path,
  cover_blur=EXCLUDED.cover_blur, cover_width=EXCLUDED.cover_width, cover_height=EXCLUDED.cover_height,
  excerpt=EXCLUDED.excerpt, content_blocks=EXCLUDED.content_blocks, published_at=EXCLUDED.published_at;

